"""Generate CLI reference from the actual argparse public interface."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from nanoforge.cli import build_parser  # noqa: E402


def render() -> str:
    parser = build_parser()
    fence = chr(96) * 3
    lines = [
        "# CLI reference", "",
        "Generated by python scripts/generate_cli_docs.py; verify with --check.",
        "Commands and flags below come from the real public parser.",
        "Examples and model/data limitations are in [training.md](training.md).",
        "Current capability and hardware acceptance gates are in [roadmap.md](roadmap.md).", "",
        "## Main command", "", fence + "text", parser.format_help().rstrip(), fence, "",
    ]
    actions = [action for action in parser._actions if isinstance(action, argparse._SubParsersAction)]
    for action in actions:
        for name, child in sorted(action.choices.items()):
            lines += [f"## {name}", "", fence + "text", child.format_help().rstrip(), fence, ""]
    lines += [
        "## Service and effect boundaries", "",
        "Localhost is the default. Nonlocal binding requires the declared authentication/request policy;",
        "TLS, tenants and an OS filesystem/network sandbox are separate deployment requirements.",
        "Project providers select a model without granting tool capabilities.",
        "Writes/tests require capabilities plus the applicable human approval policy.",
        "Network model/data loading is explicit; checks use synthetic local data.", "",
    ]
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    target = ROOT / "docs" / "cli.md"
    text = render()
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != text:
            raise SystemExit("CLI reference is stale; run scripts/generate_cli_docs.py")
        print("CLI reference matches public parser")
    else:
        target.write_text(text, encoding="utf-8")
        print("Generated docs/cli.md")


if __name__ == "__main__":
    main()

